    SELECT @CymBuildDefaultConstraintName = dc.name FROM sys.default_constraints AS dc INNER JOIN sys.columns AS c ON c.object_id = dc.parent_object_id AND c.column_id = dc.parent_column_id WHERE dc.parent_object_id = OBJECT_ID(N'[SUserInterface].[GridViewActions]', N'U') AND c.name = N'LanguageLabelId';
    IF @CymBuildDefaultConstraintName IS NOT NULL
    BEGIN
        SET @CymBuildDropDefaultSql = N'ALTER TABLE [SUserInterface].[GridViewActions] DROP CONSTRAINT ' + QUOTENAME(@CymBuildDefaultConstraintName) + N';';
        EXEC sys.sp_executesql @CymBuildDropDefaultSql;
    END;
    IF NOT EXISTS (SELECT 1 FROM sys.default_constraints AS dc INNER JOIN sys.columns AS c ON c.object_id = dc.parent_object_id AND c.column_id = dc.parent_column_id WHERE dc.parent_object_id = OBJECT_ID(N'[SUserInterface].[GridViewActions]', N'U') AND c.name = N'LanguageLabelId') ALTER TABLE [SUserInterface].[GridViewActions] ADD CONSTRAINT [DF_SUserInterface_GridViewActions_LanguageLabelId] DEFAULT ((-1)) FOR [LanguageLabelId];
    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;
