SET QUOTED_IDENTIFIER, ANSI_NULLS ON
GO

PRINT (N'Create function [SJob].[tvf_AssetsCheckForDuplicate]')
GO
PRINT (N'Create function [SJob].[tvf_AssetsCheckForDuplicate]')
GO


CREATE OR ALTER FUNCTION [SJob].[tvf_AssetsCheckForDuplicate] 
(
   @Name    NVARCHAR(100)   = NULL,
   @Number NVARCHAR(50) = NULL,
   @AddressLine1 NVARCHAR(100) = N'',
   @AddressLine2 NVARCHAR(100) = N'',
   @AddressLine3 NVARCHAR(100) = N'',
   @Town NVARCHAR(100) = N'',
   @CountyGuid UNIQUEIDENTIFIER = '00000000-0000-0000-0000-000000000000',
   @Postcode NVARCHAR(100) = N''
)
RETURNS @Results TABLE
(
	Guid UNIQUEIDENTIFIER,
	FormattedAddress NVARCHAR(600),
	MatchScore INT
)
AS
BEGIN

	--Normalise values
	DECLARE @NormPostcode   NVARCHAR(50)  = REPLACE(UPPER(LTRIM(RTRIM(ISNULL(@Postcode, '')))), ' ', '');
    DECLARE @NormNumber     NVARCHAR(50)  = UPPER(LTRIM(RTRIM(ISNULL(@Number, ''))));
    DECLARE @NormAddr1      NVARCHAR(50)  = UPPER(LTRIM(RTRIM(ISNULL(@AddressLine1, ''))));
    DECLARE @NormTown       NVARCHAR(50)  = UPPER(LTRIM(RTRIM(ISNULL(@Town, ''))));
	DECLARE @NormName       NVARCHAR(100) = UPPER(LTRIM(RTRIM(ISNULL(@Name, ''))));


INSERT INTO @Results
(
	Guid,
	FormattedAddress,
	MatchScore
)
 SELECT 
        root_hobt.Guid,
        root_hobt.FormattedAddressComma,
		(

			-- Exact Name match
            + CASE WHEN @NormName <> ''
                   AND UPPER(LTRIM(RTRIM(root_hobt.Name))) = @NormName
                   THEN 40 ELSE 0 END

			+ CASE WHEN @NormPostcode <> ''
                   AND REPLACE(UPPER(LTRIM(RTRIM(root_hobt.Postcode))), ' ', '') = @NormPostcode
                   THEN 30 ELSE 0 END

            -- Exact Number (building number) match
            + CASE WHEN @NormNumber <> ''
                   AND UPPER(LTRIM(RTRIM(root_hobt.Number))) = @NormNumber
                   THEN 20 ELSE 0 END

            -- SOUNDEX Name match (fuzzy, only if not exact)
            + CASE WHEN @NormName <> ''
                   AND root_hobt.Name <> ''
                   AND SOUNDEX(root_hobt.Name) = SOUNDEX(@Name)
                   AND UPPER(LTRIM(RTRIM(root_hobt.Name))) <> @NormName
                   THEN 15 ELSE 0 END


            -- Exact AddressLine1 match
            + CASE WHEN @NormAddr1 <> ''
                   AND UPPER(LTRIM(RTRIM(root_hobt.AddressLine1))) = @NormAddr1
                   THEN 25 ELSE 0 END

            -- SOUNDEX AddressLine1 match (fuzzy, only if not exact)
            + CASE WHEN @NormAddr1 <> ''
                   AND root_hobt.AddressLine1 <> ''
                   AND SOUNDEX(root_hobt.AddressLine1) = SOUNDEX(@AddressLine1)
                   AND UPPER(LTRIM(RTRIM(root_hobt.AddressLine1))) <> @NormAddr1
                   THEN 10 ELSE 0 END

            -- Exact Town match
            + CASE WHEN @NormTown <> ''
                   AND UPPER(LTRIM(RTRIM(root_hobt.Town))) = @NormTown
                   THEN 30 ELSE 0 END

            -- SOUNDEX Town match
            + CASE WHEN @NormTown <> ''
                   AND root_hobt.Town <> ''
                   AND SOUNDEX(root_hobt.Town) = SOUNDEX(@Town)
                   AND UPPER(LTRIM(RTRIM(root_hobt.Town))) <> @NormTown
                   THEN 30 ELSE 0 END

           
        ) AS MatchScore

    FROM SJob.Assets AS root_hobt
    LEFT JOIN SCrm.Counties AS county ON root_hobt.CountyId = county.ID
    WHERE
			root_hobt.RowStatus NOT IN (0,254)
		AND (
					(@Number = N'' OR root_hobt.Number LIKE N'%' + @Number + N'%')
				OR (@AddressLine1 <> N'' OR root_hobt.AddressLine1 LIKE N'%' + @AddressLine1 + N'%')
				OR (@AddressLine2 <> N'' OR root_hobt.AddressLine2 LIKE N'%' + @AddressLine2 + N'%')
				OR (@AddressLine3 <> N'' OR root_hobt.AddressLine3 LIKE N'%' + @AddressLine3 + N'%')
				OR (@Town <> N'' AND root_hobt.Town LIKE N'%' + @Town + N'%')
				OR (@NormAddr1 <> '' AND root_hobt.AddressLine1 <> '' AND SOUNDEX(root_hobt.AddressLine1) = SOUNDEX(@AddressLine1))
				OR (
					@CountyGuid = '00000000-0000-0000-0000-000000000000'
					OR county.Guid = @CountyGuid
				)
				OR (@Postcode <> N'' AND REPLACE(UPPER(LTRIM(RTRIM(root_hobt.Postcode))), ' ', '') = @NormPostcode)
			)


		INSERT INTO @Results
		(
			Guid,
			FormattedAddress,
			MatchScore
		)
		SELECT
		'00000000-0000-0000-0000-000000000000',
        CONCAT_WS(', ',
            NULLIF(e.PropertyNameNumber, ''),
            NULLIF(e.PropertyAddressLine1, ''),
            NULLIF(e.PropertyTown, ''),
            NULLIF(e.PropertyPostCode, '')
        )                                       AS FormattedAddress,
		
        -- === Weighted scoring (no UPRN/Geo available on enquiries) ===
        (
            -- Exact postcode match
            CASE WHEN @NormPostcode <> ''
                 AND REPLACE(UPPER(LTRIM(RTRIM(e.PropertyPostCode))), ' ', '') = @NormPostcode
                 THEN 30 ELSE 0 END

            -- Exact PropertyNameNumber match (equivalent to Asset.Name)
            + CASE WHEN @NormName <> ''
                   AND UPPER(LTRIM(RTRIM(e.PropertyNameNumber))) = @NormName
                   THEN 40 ELSE 0 END

            -- SOUNDEX PropertyNameNumber match
            + CASE WHEN @NormName <> ''
                   AND e.PropertyNameNumber <> ''
                   AND SOUNDEX(e.PropertyNameNumber) = SOUNDEX(@Name)
                   AND UPPER(LTRIM(RTRIM(e.PropertyNameNumber))) <> @NormName
                   THEN 15 ELSE 0 END

            -- Exact AddressLine1 match
            + CASE WHEN @NormAddr1 <> ''
                   AND UPPER(LTRIM(RTRIM(e.PropertyAddressLine1))) = @NormAddr1
                   THEN 25 ELSE 0 END

            -- SOUNDEX AddressLine1 match
            + CASE WHEN @NormAddr1 <> ''
                   AND e.PropertyAddressLine1 <> ''
                   AND SOUNDEX(e.PropertyAddressLine1) = SOUNDEX(@AddressLine1)
                   AND UPPER(LTRIM(RTRIM(e.PropertyAddressLine1))) <> @NormAddr1
                   THEN 10 ELSE 0 END

            -- Exact Town match
            + CASE WHEN @NormTown <> ''
                   AND UPPER(LTRIM(RTRIM(e.PropertyTown))) = @NormTown
                   THEN 10 ELSE 0 END

            -- SOUNDEX Town match
            + CASE WHEN @NormTown <> ''
                   AND e.PropertyTown <> ''
                   AND SOUNDEX(e.PropertyTown) = SOUNDEX(@Town)
                   AND UPPER(LTRIM(RTRIM(e.PropertyTown))) <> @NormTown
                   THEN 5 ELSE 0 END

        )                                       AS MatchScore

       
         

    FROM SSop.Enquiries AS e
    WHERE e.RowStatus NOT IN (0, 254)
      -- Only enquiries that entered NEW structure/property details
      AND (e.EnterNewStructureDetails = 1 OR e.PropertyId = -1)
      -- Only enquiries where NO active EnquiryService has been linked to a Quote
      AND NOT EXISTS (
          SELECT 1
          FROM SSop.EnquiryServices AS es
          WHERE es.EnquiryId = e.ID
            AND es.RowStatus NOT IN (0, 254)
            AND es.QuoteId <> -1
      )
      -- Pre-filter: at least one meaningful criterion must match
      AND (
            (@NormPostcode <> '' AND REPLACE(UPPER(LTRIM(RTRIM(e.PropertyPostCode))), ' ', '') = @NormPostcode)
         OR (@NormName <> '' AND e.PropertyNameNumber <> '' AND SOUNDEX(e.PropertyNameNumber) = SOUNDEX(@Name))
         OR (@NormAddr1 <> '' AND e.PropertyAddressLine1 <> '' AND SOUNDEX(e.PropertyAddressLine1) = SOUNDEX(@AddressLine1))
      );
		DELETE FROM @Results WHERE MatchScore <= 20;
		

		RETURN;

END;
GO
GO

/* Deploy Function SJob.tvf_EngineeringJobsFinancialOverview using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Functions\SJob.tvf_EngineeringJobsFinancialOverview.sql */
SET QUOTED_IDENTIFIER, ANSI_NULLS ON
GO

PRINT (N'Create function [SJob].[tvf_EngineeringJobsFinancialOverview]')
GO

CREATE OR ALTER FUNCTION [SJob].[tvf_EngineeringJobsFinancialOverview] 
(
    @UserId INT
)
RETURNS TABLE
            --WITH SCHEMABINDING
AS
RETURN 
SELECT   j.ID,
        j.RowStatus,
        j.RowVersion,
        j.Guid,
        j.Number,
        j.JobDescription,
        j.JobTypeID,
        jt.Name AS JobTypeName,
		i.Guid SurveyorGuid,
		i.FullName AS SurveyorName, 
		prop.FormattedAddressComma,
		COALESCE(NULLIF(client.Name, N''), N'Client Not specified') + N' / ' +COALESCE(NULLIF(agent.Name, N''), N'Agent Not specified') AS ClientAgent,
		js.IsSubjectToNDA,
		j.IsComplete,
		js.JobStatus,
		org.Name AS OrgUnit,
		j.CreatedOn AS Date,
		j.ExternalReference,
        COALESCE(NULLIF(LTRIM(RTRIM(businessUnit.Name)), N''), N'') AS BusinessUnit,
        COALESCE(NULLIF(LTRIM(RTRIM(department.Name)), N''), N'') AS Department,
		FinanceInfo.Agreed,
		FinanceInfo.Remaining,
		FinanceInfo.Invoiced,
		Products.Products
FROM    SJob.Jobs j
JOIN	SJob.JobStatus js ON (js.ID = j.ID)
JOIN    SJob.JobTypes jt ON (j.JobTypeID = jt.ID)
JOIN    SCore.Identities i ON (j.SurveyorID = i.ID)
JOIN	SJob.Assets prop ON (prop.ID = j.UprnID)
JOIN	SCrm.Accounts client ON (client.ID = j.ClientAccountID)
JOIN	SCrm.Accounts agent ON (agent.ID = j.AgentAccountID)
JOIN    SCore.OrganisationalUnits as org ON (org.ID = j.OrganisationalUnitID)
OUTER APPLY
(
    SELECT TOP (1)
        ancestor.Name
    FROM SCore.OrganisationalUnits AS ancestor
    WHERE ancestor.RowStatus NOT IN (0,254)
      AND ISNULL(ancestor.IsBusinessUnit, 0) = 1
      AND org.OrgNode IS NOT NULL
      AND ancestor.OrgNode IS NOT NULL
      AND org.OrgNode.IsDescendantOf(ancestor.OrgNode) = 1
    ORDER BY ancestor.OrgNode.GetLevel() DESC,
             ancestor.ID DESC
) AS businessUnit
OUTER APPLY
(
    SELECT TOP (1)
        ancestor.Name
    FROM SCore.OrganisationalUnits AS ancestor
    WHERE ancestor.RowStatus NOT IN (0,254)
      AND ISNULL(ancestor.IsDepartment, 0) = 1
      AND org.OrgNode IS NOT NULL
      AND ancestor.OrgNode IS NOT NULL
      AND org.OrgNode.IsDescendantOf(ancestor.OrgNode) = 1
    ORDER BY ancestor.OrgNode.GetLevel() DESC,
             ancestor.ID DESC
) AS department
OUTER APPLY
(
	SELECT 
		fin.Agreed,
		fin.Remaining,
		fin.Invoiced
	FROM SJob.Job_FeeDrawdown fin
	WHERE 
			(fin.Guid = j.Guid)
		AND (fin.Stage LIKE N'%Total (inc. Fee Cap)%')

) AS FinanceInfo
OUTER APPLY
(
    SELECT STRING_AGG(d.Code, ',') AS Products
    FROM
    (
        SELECT DISTINCT p.Code
        FROM SSop.QuoteItems qi
        JOIN SJob.Jobs jobs
            ON jobs.ID = qi.CreatedJobId
        LEFT JOIN SProd.Products p
            ON p.ID = qi.ProductId
        WHERE qi.RowStatus NOT IN (0,254)
          AND jobs.Guid = j.Guid
    ) AS d
) AS Products
WHERE   (j.RowStatus  NOT IN (0, 254))
	AND	(j.Id > 0)
	AND	(EXISTS
			(
				SELECT	1
				FROM	SCore.ObjectSecurityForUser_CanRead (j.guid, @UserId) oscr
			)
		)
GO
GO

/* Deploy Function SJob.tvf_Jobs_TeamF10ExpiryList using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Functions\SJob.tvf_Jobs_TeamF10ExpiryList.sql */
SET QUOTED_IDENTIFIER, ANSI_NULLS ON
GO

PRINT (N'Create function [SJob].[tvf_Jobs_TeamF10ExpiryList]')
GO
PRINT (N'Create function [SJob].[tvf_Jobs_TeamF10ExpiryList]')
GO
CREATE OR ALTER FUNCTION [SJob].[tvf_Jobs_TeamF10ExpiryList]
(
    @UserId INT
)
RETURNS TABLE
             --WITH SCHEMABINDING
AS
RETURN
(
    SELECT
        j.ID,
        j.RowStatus,
        j.RowVersion,
        j.Guid,
        j.Number,
        j.JobDescription,
        j.JobTypeID,
        client.Name + N' / ' + agent.Name AS ClientAgent,
        jt.Name AS JobTypeName,
        i.FullName AS Consultant,
        js.IsSubjectToNDA,
        p.FormattedAddressComma,
        F10.Reference,
        js.JobStatus,
        j.ExternalReference,
        CONVERT(NVARCHAR(19), F10.SubmissionExpiryDate, 120) AS F10Range
    FROM SJob.Jobs AS j
    JOIN SJob.JobStatus AS js ON (js.ID = j.ID)
    JOIN SJob.JobTypes AS jt ON (j.JobTypeID = jt.ID)
    JOIN SCore.Identities AS i ON (j.SurveyorID = i.ID)
    JOIN SCrm.Accounts AS client ON (client.ID = j.ClientAccountID)
    JOIN SJob.Assets AS p ON (p.ID = j.UprnID)
    JOIN SCrm.Accounts AS agent ON (agent.ID = j.AgentAccountID)

    -- Latest workflow status for this job (if any) - rowstatus safe
    OUTER APPLY
    (
        SELECT TOP (1)
            wfs.Guid AS LatestWorkflowStatusGuid,
            wfs.IsActiveStatus AS LatestIsActiveStatus
        FROM SCore.DataObjectTransition AS dot
        JOIN SCore.WorkflowStatus AS wfs ON (wfs.ID = dot.StatusID)
        WHERE (dot.RowStatus NOT IN (0, 254))
          AND (dot.DataObjectGuid = j.Guid)
        ORDER BY dot.ID DESC
    ) AS wf

    CROSS APPLY
    (
        SELECT ou1.OrgNode
        FROM SCore.OrganisationalUnits AS ou1
        JOIN SCore.Identities AS i1 ON (i1.OriganisationalUnitId = ou1.ID)
        WHERE (i1.ID = @UserId)
    ) AS CurrentUser

    CROSS APPLY
    (
        SELECT
            m.SubmissionExpiryDate,
            m.StartDateTimeUTC,
            m.DueDateTimeUTC,
            m.Reference
        FROM SJob.Milestones AS m
        JOIN SJob.MilestoneTypes AS mt ON (mt.ID = m.MilestoneTypeID)
        WHERE (m.JobID = j.ID)
          AND (mt.Code = N'F10')
          AND (m.CompletedDateTimeUTC IS NULL)
          AND (m.IsNotApplicable = 0)
          AND (m.SubmissionExpiryDate IS NOT NULL)

          -- ✅ DUE WITHIN 14 DAYS (NOT EXPIRED)
          AND (m.SubmissionExpiryDate >= GETUTCDATE())
          AND (m.SubmissionExpiryDate <  DATEADD(DAY, 14, GETUTCDATE()))

          AND (m.RowStatus NOT IN (0, 254))
          AND NOT EXISTS
          (
              SELECT 1
              FROM SJob.Milestones AS m1
              WHERE (m1.RowStatus NOT IN (0, 254))
                AND (m1.JobID = j.ID)
                AND (m1.MilestoneTypeID = m.MilestoneTypeID)
                AND (m1.SubmittedDateTimeUTC IS NOT NULL)
                AND (m1.SubmissionExpiryDate < m.SubmissionExpiryDate)
          )
    ) AS F10

    WHERE (j.RowStatus NOT IN (0, 254))

      AND EXISTS
      (
          SELECT 1
          FROM SCore.ObjectSecurityForUser_CanRead(j.Guid, @UserId) AS oscr
      )

      /* --------------------------------------------------------------------
         ACTIVE: legacy OR workflow (latest only)
      -------------------------------------------------------------------- */
      AND
      (
          CASE
              WHEN wf.LatestWorkflowStatusGuid IS NULL
                  THEN ISNULL(j.IsActive, 0)
              ELSE ISNULL(wf.LatestIsActiveStatus, 0)
          END
      ) = 1

      /* --------------------------------------------------------------------
         NOT CANCELLED: legacy OR workflow (latest only)
         Cancelled workflow status GUID: 18D8E36B-43BE-4BDE-9D0B-1F34B460AD64
      -------------------------------------------------------------------- */
      AND
      (
          CASE
              WHEN wf.LatestWorkflowStatusGuid IS NULL
                  THEN CASE WHEN ISNULL(j.IsCancelled, 0) = 0 THEN 1 ELSE 0 END
              ELSE
                  CASE
                      WHEN wf.LatestWorkflowStatusGuid = '18D8E36B-43BE-4BDE-9D0B-1F34B460AD64' THEN 0
                      ELSE 1
                  END
          END
      ) = 1

      /* --------------------------------------------------------------------
         NOT COMPLETE: legacy OR workflow (latest only)
         Completed workflow status GUID: 20D22623-283B-4088-9CEB-D944AC3E6516
      -------------------------------------------------------------------- */
      AND
      (
          CASE
              WHEN wf.LatestWorkflowStatusGuid IS NULL
                  THEN CASE WHEN (ISNULL(j.IsComplete, 0) = 0) AND (j.JobCompleted IS NULL) THEN 1 ELSE 0 END
              ELSE
                  CASE
                      WHEN wf.LatestWorkflowStatusGuid = '20D22623-283B-4088-9CEB-D944AC3E6516' THEN 0
                      ELSE 1
                  END
          END
      ) = 1

      /* --------------------------------------------------------------------
         NOT COMPLETE FOR REVIEW: legacy OR workflow (latest only)
         CompleteForReview workflow status GUID: 4BFDB215-3E27-4829-BB44-0468C92DAC82
      -------------------------------------------------------------------- */
      AND
      (
          CASE
              WHEN wf.LatestWorkflowStatusGuid IS NULL
                  THEN CASE WHEN ISNULL(j.IsCompleteForReview, 0) = 0 THEN 1 ELSE 0 END
              ELSE
                  CASE
                      WHEN wf.LatestWorkflowStatusGuid = '4BFDB215-3E27-4829-BB44-0468C92DAC82' THEN 0
                      ELSE 1
                  END
          END
      ) = 1

      AND (j.ReviewedByUserID < 0)

      -- Team scope via org node descendant check (unchanged)
      AND EXISTS
      (
          SELECT 1
          FROM SCore.OrganisationalUnits AS ou2
          WHERE (ou2.ID = i.OriganisationalUnitId)
            AND (ou2.OrgNode.IsDescendantOf(CurrentUser.OrgNode) = 1)
      )
);
GO
GO

