SET QUOTED_IDENTIFIER, ANSI_NULLS ON
GO

PRINT (N'Create procedure [SMigration].[MetadataApplyIdentityMap_Build]')
GO

PRINT (N'Create procedure [SMigration].[MetadataApplyIdentityMap_Build]')
