                    ISNULL(CONVERT(NVARCHAR(36), t.UserGuid), N'') AS UserGuid,
                    ISNULL(t.JobTitle, N'') AS JobTitle,
                    ISNULL(CONVERT(NVARCHAR(36), ou.Guid), N'') AS OrganisationalUnitGuid,
                    CONVERT(NVARCHAR(5), ISNULL(t.IsActive, 1)) AS IsActive,
