/* Deploy StoredProcedure SMigration.OnboardingRunEntitySelection_Default using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Procedures\SMigration.OnboardingRunEntitySelection_Default.sql */
SET QUOTED_IDENTIFIER, ANSI_NULLS ON
GO

PRINT (N'Create procedure [SMigration].[OnboardingRunEntitySelection_Default]')
GO
PRINT (N'Create procedure [SMigration].[OnboardingRunEntitySelection_Default]')
GO

CREATE OR ALTER PROCEDURE [SMigration].[OnboardingRunEntitySelection_Default]
(
    @RunGuid UNIQUEIDENTIFIER
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @RunGuid IS NULL
        THROW 62200, 'RunGuid is required for OnBoarding entity selection defaults.', 1;

    EXEC SMigration.OnboardingEntityScope_Seed;

    DECLARE
        @SelectionGuid UNIQUEIDENTIFIER,
        @EntityScopeGuid UNIQUEIDENTIFIER,
        @EntityCode NVARCHAR(100),
        @DefaultSelected BIT;

    DECLARE selection_cursor CURSOR LOCAL FAST_FORWARD FOR
        SELECT
            NEWID() AS SelectionGuid,
            es.Guid AS EntityScopeGuid,
            es.Code AS EntityCode,
            es.DefaultSelected
        FROM SMigration.Onboarding_EntityScope AS es
        WHERE es.RowStatus NOT IN (0,254)
          AND es.IsSupportData = 0
          AND NOT EXISTS
          (
              SELECT 1
              FROM SMigration.Onboarding_RunEntitySelections AS existing
              WHERE existing.RunGuid = @RunGuid
                AND existing.EntityCode = es.Code
          )
        ORDER BY es.DisplayOrder;

    OPEN selection_cursor;
    FETCH NEXT FROM selection_cursor INTO @SelectionGuid, @EntityScopeGuid, @EntityCode, @DefaultSelected;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        EXEC SMigration.MetadataDataObject_Ensure
            @Guid = @SelectionGuid,
            @SchemeName = N'SMigration',
            @ObjectName = N'Onboarding_RunEntitySelections';

        INSERT INTO SMigration.Onboarding_RunEntitySelections
        (
            Guid,
            RowStatus,
            RunGuid,
            EntityScopeGuid,
            EntityCode,
            IsSelected,
            SelectionSource,
            SelectedByUserId,
            SelectedOnUtc
        )
        VALUES
        (
            @SelectionGuid,
            1,
            @RunGuid,
            @EntityScopeGuid,
            @EntityCode,
            @DefaultSelected,
            N'Default',
            ISNULL(SCore.GetCurrentUserId(), -1),
            SYSUTCDATETIME()
        );

        FETCH NEXT FROM selection_cursor INTO @SelectionGuid, @EntityScopeGuid, @EntityCode, @DefaultSelected;
    END;

    CLOSE selection_cursor;
    DEALLOCATE selection_cursor;

    UPDATE sel
    SET
        RowStatus = CASE WHEN sel.RowStatus IN (0,254) THEN 1 ELSE sel.RowStatus END,
        EntityScopeGuid = es.Guid
    FROM SMigration.Onboarding_RunEntitySelections AS sel
    INNER JOIN SMigration.Onboarding_EntityScope AS es
        ON es.Code = sel.EntityCode
       AND es.RowStatus NOT IN (0,254)
       AND es.IsSupportData = 0
    WHERE sel.RunGuid = @RunGuid;
END;
GO
GO

/* Deploy StoredProcedure SMigration.OnboardingRunEntitySelection_List using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Procedures\SMigration.OnboardingRunEntitySelection_List.sql */
SET QUOTED_IDENTIFIER, ANSI_NULLS ON
GO

PRINT (N'Create procedure [SMigration].[OnboardingRunEntitySelection_List]')
GO
PRINT (N'Create procedure [SMigration].[OnboardingRunEntitySelection_List]')
GO

CREATE OR ALTER PROCEDURE [SMigration].[OnboardingRunEntitySelection_List]
(
    @RunGuid UNIQUEIDENTIFIER
)
AS
BEGIN
    SET NOCOUNT ON;

    IF @RunGuid IS NULL
        THROW 62210, 'RunGuid is required to list OnBoarding entity selections.', 1;

    EXEC SMigration.OnboardingEntityScope_Seed;

    SELECT
        es.Guid AS EntityScopeGuid,
        es.Code AS EntityCode,
        es.Name AS EntityName,
        es.Description,
        es.StageTableName,
        es.DisplayOrder,
        CONVERT(BIT, ISNULL(sel.IsSelected, es.DefaultSelected)) AS IsSelected,
        es.DefaultSelected,
        es.CanDeselect,
        es.IsRequired,
        es.RequiredDependencyCodes,
        sel.Guid AS SelectionGuid,
        ISNULL(sel.SelectionSource, N'Default') AS SelectionSource,
        ISNULL(CONVERT(NVARCHAR(30), sel.SelectedOnUtc, 126), N'') AS SelectedOnUtc,
        es.Category,
        es.ScopeType,
        es.IsImplemented,
        es.IsSupportData,
        es.HandlerKey,
        es.PrimaryEntityTypeGuid,
        es.SourceSchemaName,
        es.SourceTableName
    FROM SMigration.Onboarding_EntityScope AS es
    LEFT JOIN SMigration.Onboarding_RunEntitySelections AS sel
        ON sel.RunGuid = @RunGuid
       AND sel.EntityCode = es.Code
       AND sel.RowStatus NOT IN (0,254)
    WHERE es.RowStatus NOT IN (0,254)
      AND es.IsSupportData = 0
    ORDER BY
        CASE es.Category
            WHEN N'Access Foundation' THEN 10
            WHEN N'Operational Configuration' THEN 20
            WHEN N'Additional Eligible Record Types' THEN 30
            WHEN N'Internal / Support Data' THEN 90
            ELSE 80
        END,
        es.DisplayOrder,
        es.Code;
END;
GO
GO

/* Deploy StoredProcedure SMigration.OnboardingRunEntitySelection_Save using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Procedures\SMigration.OnboardingRunEntitySelection_Save.sql */
SET QUOTED_IDENTIFIER, ANSI_NULLS ON
GO

PRINT (N'Create procedure [SMigration].[OnboardingRunEntitySelection_Save]')
GO
PRINT (N'Create procedure [SMigration].[OnboardingRunEntitySelection_Save]')
GO

CREATE OR ALTER PROCEDURE [SMigration].[OnboardingRunEntitySelection_Save]
(
    @RunGuid UNIQUEIDENTIFIER,
    @SelectionsJson NVARCHAR(MAX)
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @RunGuid IS NULL
        THROW 62220, 'RunGuid is required to save OnBoarding entity selections.', 1;

    IF ISNULL(@SelectionsJson, N'') = N'' OR ISJSON(@SelectionsJson) <> 1
        THROW 62221, 'SelectionsJson must be a valid JSON array.', 1;

    EXEC SMigration.OnboardingRunEntitySelection_Default @RunGuid = @RunGuid;

    DECLARE @Requested TABLE
    (
        EntityCode NVARCHAR(100) NOT NULL PRIMARY KEY,
        IsSelected BIT NOT NULL
    );

    INSERT INTO @Requested
    (
        EntityCode,
        IsSelected
    )
    SELECT
        LTRIM(RTRIM(JSON_VALUE(value, N'$.EntityCode'))) AS EntityCode,
        CONVERT(BIT,
            CASE
                WHEN LOWER(ISNULL(JSON_VALUE(value, N'$.IsSelected'), N'')) IN (N'true', N'1') THEN 1
                ELSE 0
            END) AS IsSelected
    FROM OPENJSON(@SelectionsJson)
    WHERE ISNULL(LTRIM(RTRIM(JSON_VALUE(value, N'$.EntityCode'))), N'') <> N'';

    IF NOT EXISTS (SELECT 1 FROM @Requested)
        THROW 62222, 'At least one OnBoarding entity selection is required.', 1;

    IF EXISTS
    (
        SELECT 1
        FROM @Requested AS requested
        WHERE NOT EXISTS
        (
            SELECT 1
            FROM SMigration.Onboarding_EntityScope AS scope
            WHERE scope.Code = requested.EntityCode
              AND scope.RowStatus NOT IN (0,254)
              AND scope.IsSupportData = 0
        )
    )
    BEGIN
        THROW 62223, 'One or more requested OnBoarding entity selections is not registered in SMigration.Onboarding_EntityScope.', 1;
    END;

    IF EXISTS
    (
        SELECT 1
        FROM @Requested AS requested
        INNER JOIN SMigration.Onboarding_EntityScope AS scope
            ON scope.Code = requested.EntityCode
           AND scope.RowStatus NOT IN (0,254)
           AND scope.IsSupportData = 0
        WHERE requested.IsSelected = 0
          AND (scope.CanDeselect = 0 OR scope.IsRequired = 1)
    )
    BEGIN
        THROW 62224, 'One or more required OnBoarding entity scopes cannot be deselected.', 1;
    END;

    DECLARE @Final TABLE
    (
        EntityScopeGuid UNIQUEIDENTIFIER NOT NULL,
        EntityCode NVARCHAR(100) NOT NULL PRIMARY KEY,
        EntityName NVARCHAR(200) NOT NULL,
        RequiredDependencyCodes NVARCHAR(1000) NOT NULL,
        IsSelected BIT NOT NULL
    );

    INSERT INTO @Final
    (
        EntityScopeGuid,
        EntityCode,
        EntityName,
        RequiredDependencyCodes,
        IsSelected
    )
    SELECT
        scope.Guid,
        scope.Code,
        scope.Name,
        scope.RequiredDependencyCodes,
        CONVERT(BIT, COALESCE(requested.IsSelected, currentSelection.IsSelected, scope.DefaultSelected)) AS IsSelected
    FROM SMigration.Onboarding_EntityScope AS scope
    LEFT JOIN SMigration.Onboarding_RunEntitySelections AS currentSelection
        ON currentSelection.RunGuid = @RunGuid
       AND currentSelection.EntityCode = scope.Code
       AND currentSelection.RowStatus NOT IN (0,254)
    LEFT JOIN @Requested AS requested
        ON requested.EntityCode = scope.Code
    WHERE scope.RowStatus NOT IN (0,254)
      AND scope.IsSupportData = 0;

    DECLARE @DependencyErrors NVARCHAR(MAX) = N'';

    ;WITH DependencyRows AS
    (
        SELECT
            selected.EntityCode,
            selected.EntityName,
            DependencyCode = LTRIM(RTRIM(split.value))
        FROM @Final AS selected
        CROSS APPLY STRING_SPLIT(selected.RequiredDependencyCodes, N',') AS split
        WHERE selected.IsSelected = 1
          AND ISNULL(LTRIM(RTRIM(split.value)), N'') <> N''
    ), MissingDependencies AS
    (
        SELECT
            dependency.EntityCode,
            dependency.EntityName,
            dependency.DependencyCode
        FROM DependencyRows AS dependency
        LEFT JOIN @Final AS requiredScope
            ON requiredScope.EntityCode = dependency.DependencyCode
           AND requiredScope.IsSelected = 1
        WHERE requiredScope.EntityCode IS NULL
    )
    SELECT
        @DependencyErrors = STRING_AGG(CONCAT(EntityCode, N' requires ', DependencyCode), N'; ')
    FROM MissingDependencies;

    IF ISNULL(@DependencyErrors, N'') <> N''
    BEGIN
        DECLARE @DependencyMessage NVARCHAR(2048) = LEFT(CONCAT(N'OnBoarding entity scope dependency validation failed: ', @DependencyErrors), 2048);
        THROW 62225, @DependencyMessage, 1;
    END;

    DECLARE
        @EntityScopeGuid UNIQUEIDENTIFIER,
        @EntityCode NVARCHAR(100),
        @IsSelected BIT,
        @SelectionGuid UNIQUEIDENTIFIER;

    DECLARE save_cursor CURSOR LOCAL FAST_FORWARD FOR
        SELECT
            final.EntityScopeGuid,
            final.EntityCode,
            final.IsSelected,
            existing.Guid AS SelectionGuid
        FROM @Final AS final
        LEFT JOIN SMigration.Onboarding_RunEntitySelections AS existing
            ON existing.RunGuid = @RunGuid
           AND existing.EntityCode = final.EntityCode
        ORDER BY final.EntityCode;

    OPEN save_cursor;
    FETCH NEXT FROM save_cursor INTO @EntityScopeGuid, @EntityCode, @IsSelected, @SelectionGuid;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        SET @SelectionGuid = ISNULL(@SelectionGuid, NEWID());

        EXEC SMigration.MetadataDataObject_Ensure
            @Guid = @SelectionGuid,
            @SchemeName = N'SMigration',
            @ObjectName = N'Onboarding_RunEntitySelections';

        IF EXISTS
        (
            SELECT 1
            FROM SMigration.Onboarding_RunEntitySelections AS existing
            WHERE existing.RunGuid = @RunGuid
              AND existing.EntityCode = @EntityCode
        )
        BEGIN
            UPDATE SMigration.Onboarding_RunEntitySelections
            SET
                RowStatus = 1,
                EntityScopeGuid = @EntityScopeGuid,
                IsSelected = @IsSelected,
                SelectionSource = N'Manual',
                SelectedByUserId = ISNULL(SCore.GetCurrentUserId(), -1),
                SelectedOnUtc = SYSUTCDATETIME()
            WHERE RunGuid = @RunGuid
              AND EntityCode = @EntityCode;
        END
        ELSE
        BEGIN
            INSERT INTO SMigration.Onboarding_RunEntitySelections
            (
                Guid,
                RowStatus,
                RunGuid,
                EntityScopeGuid,
                EntityCode,
                IsSelected,
                SelectionSource,
                SelectedByUserId,
                SelectedOnUtc
            )
            VALUES
            (
                @SelectionGuid,
                1,
                @RunGuid,
                @EntityScopeGuid,
                @EntityCode,
                @IsSelected,
                N'Manual',
                ISNULL(SCore.GetCurrentUserId(), -1),
                SYSUTCDATETIME()
            );
        END;

        FETCH NEXT FROM save_cursor INTO @EntityScopeGuid, @EntityCode, @IsSelected, @SelectionGuid;
    END;

    CLOSE save_cursor;
    DEALLOCATE save_cursor;

    EXEC SMigration.OnboardingRunEntitySelection_List @RunGuid = @RunGuid;
END;
GO
GO

