/*
    CymBuild generated canonical schema source.
    Generated by       : CYB-361 R7C4 selected DEV schema source sync
    Object             : StoredProcedure SSop.EnquiryCreateQuotes
    Source schema hash : 89D8608877ABE9EA01A4ACC5D7D9EEE51A9B00480F86A6FB16847D64D34EE2EA
    Definition SHA-256 : 8292652351F6A54B1B55194E5F121044AD7023574B43B39D147F7E5227D3EEF6

    This deterministic file was synchronized from an explicitly selected, validated and accepted
